update t_user set

    email =#{email},


    phone =#{phone},


    password =#{password}

where name =#{name}

mapper.select:
select uf.follower_id userId ,tu.name ,tu.head_pic_url from user_follow uf
inner join t_user tu on tu.user_id = uf.follower_id
where uf.status =1 and uf.following_id =#{param1}

select uf.following_id userId,tu.name ,tu.head_pic_url from user_follow uf
inner join t_user tu on tu.user_id = uf.following_id
where uf.status =1 and uf.follower_id =#{param1}

select uf.following_id userId ,tu.name ,tu.head_pic_url from user_follow uf
inner join t_user tu on tu.user_id = uf.following_id
where uf.status =-1 and uf.follower_id =#{param1}
